import {titre,meanSelected,titreTasks,strengthTasks,hydrogenFactor} from './titration-models.js?v=20261023-physicscomplete01';
import {showTitration} from './titration-scenes.js?v=20261023-physicscomplete01';
const input=(id,label)=>`<label class="field-label" for="${id}">${label}</label><input class="lab-input" id="${id}" type="number" step="any">`;
const select=(id,label,options,value='')=>`<label class="field-label" for="${id}">${label}</label><select class="lab-select" id="${id}"><option value="">Choose…</option>${options.map(([v,text])=>`<option value="${v}" ${value===v?'selected':''}>${text}</option>`).join('')}</select>`;
export function mountTitrationWidget(l,p,root,{save,done,feedback}){const w=p.widget;w.task??=0;w.answers??={};w.passed??=[];const i=w.task,a=w.answers[i]??={},strength=l.widget==='titrate-strength',t=(strength?strengthTasks:titreTasks)[i],$=s=>root.querySelector(s);a.indices??=[];const result=strength?null:{titre:titre(t.initial,t.final),mean:meanSelected(t.readings,t.indices)};
root.innerHTML=`<p><b>Case ${i+1} / 3</b></p>`+(strength?`<p>${t.name}: ${t.c} mol/dm³, ${t.ionisation} ionisation. Classify strength and concentration relative to 0.10 mol/dm³.</p>`+select('acidStrength','Strength',[['strong','Strong'],['weak','Weak']],a.strength)+select('acidRelative','Concentration versus reference',[['dilute','More dilute'],['same','Same concentration'],['concentrated','More concentrated']],a.relative)+`<p>Separate pH comparison: H⁺ concentration at pH ${t.firstPH} divided by H⁺ concentration at pH ${t.secondPH}. Enter the factor (a fraction is allowed).</p>`+input('hydrogenFactor','H⁺ concentration factor'):`<p>Initial ${t.initial.toFixed(2)} cm³; final ${t.final.toFixed(2)} cm³. Rough titre ${t.rough.toFixed(2)} cm³. Select ALL precise repeats that form the largest group within 0.10 cm³; exclude rough and any outlier.</p>`+input('titreAnswer','Delivered titre / cm³')+t.readings.map((v,j)=>`<label class="titre-check"><input type="checkbox" data-repeat="${j}" ${a.indices.includes(j)?'checked':''}> Precise repeat ${j+1}: ${v.toFixed(2)} cm³</label>`).join('')+input('titreMean','Mean of selected precise repeats / cm³'))+`<button class="secondary" id="checkTitration">Check the account</button><button class="secondary" id="nextTitration">Next case →</button><p id="titrationProgress">${w.passed.length} / 3 cases correct</p>`;
const numericFields=strength?[['factor','hydrogenFactor']]:[['titre','titreAnswer'],['mean','titreMean']];numericFields.forEach(([k,id])=>{$('#'+id).value=a[k]||'';$('#'+id).oninput=e=>{a[k]=e.target.value;save();};});if(strength){$('#acidStrength').onchange=e=>{a.strength=e.target.value;save();};$('#acidRelative').onchange=e=>{a.relative=e.target.value;save();};}else root.querySelectorAll('[data-repeat]').forEach(el=>el.onchange=()=>{a.indices=[...root.querySelectorAll('[data-repeat]:checked')].map(x=>Number(x.dataset.repeat));save();});showTitration(strength?'strength':'volume',t,w.passed.includes(i),result);
$('#checkTitration').onclick=()=>{const near=(k,n,tol)=>a[k]!==undefined&&a[k]!==''&&Number.isFinite(Number(a[k]))&&Math.abs(Number(a[k])-n)<=tol;const ok=strength?a.strength===t.strength&&a.relative===t.relative&&near('factor',hydrogenFactor(t.firstPH,t.secondPH),.00001):near('titre',result.titre,.001)&&near('mean',result.mean,.001)&&a.indices.join(',')===t.indices.join(',');if(!ok){feedback(strength?'Strength follows complete/partial ionisation. Compare concentration with 0.10 mol/dm³ separately. For first-pH/second-pH H⁺ ratio use 10^(second pH−first pH), including fractions when first pH is higher.':'Subtract initial from final. Choose the largest precise group whose full range is at most 0.10 cm³, exclude the rough/outlier, and average only those selected readings.',true);return;}if(!w.passed.includes(i))w.passed.push(i);save();showTitration(strength?'strength':'volume',t,true,result);$('#titrationProgress').textContent=w.passed.length+' / 3 cases correct';feedback('Correct. Your account matches the supplied data and stated comparison rule.');if(w.passed.length===3){p.widgetDone=true;save();done();}};$('#nextTitration').onclick=()=>{w.task=(i+1)%3;save();mountTitrationWidget(l,p,root,{save,done,feedback});};}
